sql:
SELECT PetType, avg(pet_age) AS average_age, max(pet_age) AS maximum_age 
FROM Pets 
GROUP BY PetType;

SELECT cl.Model FROM cars_data AS cd 
JOIN car_names AS cl ON cd.Id = cl.MakeId 
ORDER BY cd.Horsepower ASC LIMIT 1;

SELECT COUNT(*) 
FROM model_list 
WHERE Maker IN (SELECT Id FROM car_makers WHERE Country = 'USA');

SELECT car_makers.Maker, model_list.Model 
FROM model_list 
JOIN car_makers ON model_list.Maker = car_makers.Id;
